def get_sts9_blocks():
    # Standard STS(9) construction (affine plane of order 3)
    # Points 0-8
    blocks = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8],
        [0, 3, 6], [1, 4, 7], [2, 5, 8],
        [0, 4, 8], [1, 5, 6], [2, 3, 7],
        [0, 5, 7], [1, 3, 8], [2, 4, 6]
    ]
    return blocks

def construct_bibd():
    sts_blocks = get_sts9_blocks()
    # Repeat each block 3 times
    all_blocks = []
    for b in sts_blocks:
        for _ in range(3):
            all_blocks.append(b)

    # Create 9x36 matrix
    matrix = [[0 for _ in range(36)] for _ in range(9)]
    for col_idx, block in enumerate(all_blocks):
        for point in block:
            matrix[point][col_idx] = 1

    return matrix

matrix = construct_bibd()
# Flatten the matrix
flat_matrix = [val for row in matrix for val in row]

# Verify properties
def verify(matrix):
    v = 9
    b = 36
    # Row sums
    for i in range(v):
        if sum(matrix[i]) != 12:
            return False, f"Row {i} sum is {sum(matrix[i])}"
    # Column sums
    for j in range(b):
        col_sum = sum(matrix[i][j] for i in range(v))
        if col_sum != 3:
            return False, f"Column {j} sum is {col_sum}"
    # Inner products
    for i1 in range(v):
        for i2 in range(i1 + 1, v):
            inner_prod = sum(matrix[i1][j] * matrix[i2][j] for j in range(b))
            if inner_prod != 3:
                return False, f"Inner product of row {i1} and {i2} is {inner_prod}"
    return True, "OK"

is_valid, msg = verify(matrix)
print(f"Valid: {is_valid}, Message: {msg}")
print(f"Length: {len(flat_matrix)}")
